<?php require '_init.php';$id=number('id',true);$p=$id?query('SELECT * FROM products WHERE id=?',[$id])->fetch():['name'=>'','brand_id'=>1,'category_id'=>1,'price'=>'','stock'=>0,'size_ml'=>100,'concentration'=>'Eau de Parfum','description'=>'','top_notes'=>'','heart_notes'=>'','base_notes'=>'','is_sold_out'=>0];if(!$p){http_response_code(404);exit('Product not found.');}$errors=[];$images=$id?query('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order,id',[$id])->fetchAll():[];
if(post()){verify_csrf();$action=textval('action');if($action==='remove_image'){$imageId=number('image_id');if(count($images)<=2)$errors[]='Keep at least two product images.';else{query('DELETE FROM product_images WHERE id=? AND product_id=?',[$imageId,$id]);flash('Image removed from gallery.');redirect('admin/product-edit.php?id='.$id);}}elseif($action==='cover'){query('UPDATE product_images SET sort_order=1 WHERE product_id=?',[$id]);query('UPDATE product_images SET sort_order=0 WHERE id=? AND product_id=?',[number('image_id'),$id]);flash('Cover image changed.');redirect('admin/product-edit.php?id='.$id);}else{
foreach(['name','concentration','description','top_notes','heart_notes','base_notes','price'] as $f)$p[$f]=textval($f);foreach(['brand_id','category_id','stock','size_ml'] as $f)$p[$f]=number($f);$p['is_sold_out']=isset($_POST['is_sold_out'])?1:0;
if(mb_strlen($p['name'])<2||mb_strlen($p['name'])>160)$errors[]='Product name must be 2–160 characters.';if(!preg_match('/^\d{1,6}(\.\d{1,2})?$/',$p['price'])||(float)$p['price']<=0)$errors[]='Price must be greater than zero and at most 999999.99.';if(!ctype_digit(textval('stock'))||$p['stock']>1000000)$errors[]='Stock must be a whole number from 0 to 1000000.';if($p['size_ml']<1||$p['size_ml']>2000)$errors[]='Size must be 1–2000 ml.';if(mb_strlen($p['description'])<20||mb_strlen($p['description'])>5000)$errors[]='Description must be 20–5000 characters.';foreach(['top_notes','heart_notes','base_notes'] as $f)if(mb_strlen($p[$f])<2||mb_strlen($p[$f])>500)$errors[]='Each note field must be 2–500 characters.';if(!in_array($p['concentration'],['Eau de Parfum','Eau de Toilette','Extrait de Parfum','Parfum'],true))$errors[]='Select a valid concentration.';if(!query('SELECT id FROM brands WHERE id=?',[$p['brand_id']])->fetch()||!query('SELECT id FROM categories WHERE id=?',[$p['category_id']])->fetch())$errors[]='Select a valid brand and category.';
$uploads=[];$files=$_FILES['images']??null;if($files&&is_array($files['name']))foreach($files['name'] as $i=>$name){if($files['error'][$i]===UPLOAD_ERR_NO_FILE)continue;if($files['error'][$i]!==UPLOAD_ERR_OK||$files['size'][$i]>5*1024*1024){$errors[]='Each image must upload successfully and be no larger than 5 MB.';continue;}$tmp=$files['tmp_name'][$i];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$dim=@getimagesize($tmp);if(!isset($types[$mime])||!$dim||$dim[0]*$dim[1]>20000000){$errors[]='Use a valid JPG, PNG or WebP image, up to 20 megapixels.';continue;}$uploads[]=[$tmp,'images/uploads/'.bin2hex(random_bytes(16)).'.'.$types[$mime]];}
if(count($images)+count($uploads)<2)$errors[]='Upload at least two different photos for this product.';if(count($images)+count($uploads)>8)$errors[]='A product can have at most eight images.';
if(!$errors){$moved=[];try{db()->beginTransaction();$fields=['name','brand_id','category_id','price','stock','size_ml','concentration','description','top_notes','heart_notes','base_notes','is_sold_out'];$vals=array_map(fn($f)=>$p[$f],$fields);if($id){query('UPDATE products SET '.implode(',',array_map(fn($f)=>$f.'=?',$fields)).' WHERE id=?',array_merge($vals,[$id]));}else{query('INSERT INTO products('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')',$vals);$id=(int)db()->lastInsertId();}foreach($uploads as $i=>[$tmp,$path]){if(!move_uploaded_file($tmp,__DIR__.'/../'.$path))throw new RuntimeException('Upload failed. Check the images/uploads folder permission.');$moved[]=$path;query('INSERT INTO product_images(product_id,path,sort_order) VALUES (?,?,?)',[$id,$path,count($images)+$i]);}db()->commit();flash('Perfume saved.');redirect('admin/product-edit.php?id='.$id);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();foreach($moved as $path)@unlink(__DIR__.'/../'.$path);error_log((string)$e);$errors[]='Unable to save. Check image upload permissions and try again.';}}}}
$pageTitle=$id?'Edit perfume':'Add perfume';require '../includes/header.php';?><section class="container section"><a href="<?=e(url('admin/products.php'))?>">← Products</a><h1><?=e($pageTitle)?></h1><?php errors($errors);?><form method="post" enctype="multipart/form-data" class="panel" data-validate><?php csrf();?><input type="hidden" name="action" value="save"><div class="form-grid"><label>Name<input name="name" value="<?=e($p['name'])?>" minlength="2" maxlength="160" required></label><label>Brand<select name="brand_id"><?php foreach(query('SELECT * FROM brands ORDER BY name')->fetchAll() as $b):?><option value="<?=$b['id']?>" <?=$p['brand_id']==$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><label>Category<select name="category_id"><?php foreach(query('SELECT * FROM categories ORDER BY id')->fetchAll() as $c):?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Price (USD)<input type="number" name="price" min="0.01" max="999999.99" step="0.01" required value="<?=e($p['price'])?>"></label><label>Stock quantity<input type="number" name="stock" min="0" max="1000000" required value="<?=$p['stock']?>"></label><label>Size (ml)<input type="number" name="size_ml" min="1" max="2000" required value="<?=$p['size_ml']?>"></label><label>Concentration<select name="concentration"><?php foreach(['Eau de Parfum','Eau de Toilette','Extrait de Parfum','Parfum'] as $c):?><option <?=$p['concentration']===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="is_sold_out" value="1" <?=$p['is_sold_out']?'checked':''?>> Mark as Sold Out</label></div><label>Description<textarea name="description" rows="4" minlength="20" maxlength="5000" required><?=e($p['description'])?></textarea></label><div class="form-grid"><?php foreach(['top_notes'=>'Top notes','heart_notes'=>'Heart notes','base_notes'=>'Base notes'] as $f=>$label):?><label><?=$label?><input name="<?=$f?>" value="<?=e($p[$f])?>" minlength="2" maxlength="500" required></label><?php endforeach;?></div><label>Product photos (JPG, PNG, WebP; 5 MB each; gallery must have 2–8 photos)<input type="file" name="images[]" multiple accept="image/jpeg,image/png,image/webp" <?=$id?'':'required'?>></label><button>Save perfume</button></form><h2>Image gallery</h2><div class="admin-gallery"><?php foreach($images as $i=>$im):?><div class="panel"><img src="<?=e(url($im['path']))?>" alt="Product photo <?=$i+1?>"><form method="post"><?php csrf();?><input type="hidden" name="image_id" value="<?=$im['id']?>"><button name="action" value="cover" class="outline"><?=$i===0?'Cover photo':'Make cover'?></button><button name="action" value="remove_image" class="link" <?=count($images)<=2?'disabled':''?>>Remove</button></form></div><?php endforeach;?></div></section><?php require '../includes/footer.php';?>
